<?php use MediaPitch\Core\Csrf; $g=$guide ?? []; $rows=$g['products'] ?? []; if(!$rows)$rows=[[]]; ?>
<form method="post" action="<?= e(url('admin/guides/save')) ?>" class="panel form-panel"><?= Csrf::field() ?><?php if(!empty($g['id'])):?><input type="hidden" name="id" value="<?= (int)$g['id'] ?>"><?php endif;?>
<div class="form-grid"><label class="span-2">Title<input name="title" required value="<?= e($g['title'] ?? '') ?>"></label><label>Slug<input name="slug" required value="<?= e($g['slug'] ?? '') ?>"></label><label>Category<select name="category_id"><option value="">—</option><?php foreach($categories as $c):?><option value="<?= (int)$c['id'] ?>" <?= (int)($g['category_id']??0)===(int)$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach;?></select></label><label>Status<select name="status"><option value="draft" <?= ($g['status']??'draft')==='draft'?'selected':'' ?>>Draft</option><option value="scheduled" <?= ($g['status']??'')==='scheduled'?'selected':'' ?>>Scheduled</option><option value="published" <?= ($g['status']??'')==='published'?'selected':'' ?>>Published</option></select></label><label>Publish date<input type="datetime-local" name="published_at" value="<?= !empty($g['published_at'])?e(date('Y-m-d\TH:i',strtotime($g['published_at']))):'' ?>"></label><label class="span-2">Excerpt<textarea name="excerpt" rows="3"><?= e($g['excerpt'] ?? '') ?></textarea></label><label class="span-2">Body<textarea name="body" rows="10"><?= e($g['body'] ?? '') ?></textarea></label><label class="span-2">Featured image URL<input type="url" name="featured_image_url" value="<?= e($g['featured_image_url'] ?? '') ?>"></label><label>SEO title<input name="seo_title" value="<?= e($g['seo_title'] ?? '') ?>"></label><label>Meta description<textarea name="meta_description" rows="3"><?= e($g['meta_description'] ?? '') ?></textarea></label></div>
<div class="panel-head subhead"><div><h2>Ranked products</h2><p>Add any number of products. A product can be reused in other guides.</p></div><button type="button" class="secondary-button" id="add-product">+ Add row</button></div>
<div id="product-rows"><?php foreach($rows as $r):?><div class="product-row"><label>Rank<input type="number" min="1" name="rank[]" value="<?= e(isset($r['rank_position'])?(string)$r['rank_position']:'') ?>"></label><label class="grow">Product<select name="product_id[]"><option value="">Choose product</option><?php foreach($productOptions as $p):?><option value="<?= (int)$p['id'] ?>" <?= (int)($r['product_id']??0)===(int)$p['id']?'selected':'' ?>><?= e($p['title']) ?></option><?php endforeach;?></select></label><label>Score<input type="number" min="0" max="10" step="0.1" name="product_score[]" value="<?= e(isset($r['score'])?(string)$r['score']:'') ?>"></label><label>Best for<input name="product_best_for[]" value="<?= e($r['best_for_label'] ?? '') ?>"></label><label class="wide">Recommendation<textarea name="recommendation[]" rows="2"><?= e($r['recommendation'] ?? '') ?></textarea></label><label>CTA text<input name="cta_text[]" value="<?= e($r['cta_text'] ?? 'Check Price on Amazon') ?>"></label><button type="button" class="remove-row">Remove</button></div><?php endforeach;?></div>
<div class="form-actions"><a class="secondary-button" href="<?= e(url('admin/guides')) ?>">Cancel</a><button class="primary-button">Save guide</button></div></form>
<template id="product-template"><div class="product-row"><label>Rank<input type="number" min="1" name="rank[]"></label><label class="grow">Product<select name="product_id[]"><option value="">Choose product</option><?php foreach($productOptions as $p):?><option value="<?= (int)$p['id'] ?>"><?= e($p['title']) ?></option><?php endforeach;?></select></label><label>Score<input type="number" min="0" max="10" step="0.1" name="product_score[]"></label><label>Best for<input name="product_best_for[]"></label><label class="wide">Recommendation<textarea name="recommendation[]" rows="2"></textarea></label><label>CTA text<input name="cta_text[]" value="Check Price on Amazon"></label><button type="button" class="remove-row">Remove</button></div></template>
<script>const rows=document.getElementById('product-rows'),tpl=document.getElementById('product-template');document.getElementById('add-product').onclick=()=>rows.append(tpl.content.cloneNode(true));document.addEventListener('click',e=>{if(e.target.classList.contains('remove-row')&&rows.children.length>1)e.target.closest('.product-row').remove()});</script>